class CustomRAII {
    int* buffer;
public:
    explicit CustomRAII(size_t s) : buffer(new int[s]) {}
    ~CustomRAII() { delete[] buffer; }
    CustomRAII(const CustomRAII&) = delete; // Prevent leaks
};

struct HeavyResource {};

void use_smart_ptr() {
    // std::make_unique acquires resource
    auto ptr = std::make_unique<HeavyResource>();
    // Resource automatically released when ptr goes out of scope
}

std::mutex global_mtx;

void safe_function() {
    // Acquire lock immediately
    std::lock_guard<std::mutex> lock(global_mtx);
    // Critical section
    // Lock automatically released on exit (even if exception occurs)
}

void process_file() {
    std::fstream file("data.txt", std::ios::out);
    if (!file.is_open()) return;

    file << "Writing data...";
} // File handle closed automatically by fstream destructor
